const fs = require('fs');
const fsp = fs.promises;
const path = require('path');
const crypto = require('crypto');
const env = require('../config/env');

const dirs = {
  tmp: path.join(env.storageDir, 'tmp'), // uploads waiting to be attached to a book
  books: path.join(env.storageDir, 'books'), // PRIVATE: never served as static files
  covers: path.join(env.storageDir, 'covers'), // public cover images
};

function init() {
  for (const dir of Object.values(dirs)) fs.mkdirSync(dir, { recursive: true });
}

// Storage keys are always generated by the server. This check makes sure a key
// can never contain "..", slashes, or anything that could escape the folder.
const KEY_RE = /^[a-f0-9-]{36}(\.[a-z]{3,4})?$/;

function safePath(kind, key) {
  if (!KEY_RE.test(key)) throw new Error('Invalid storage key');
  return path.join(dirs[kind], key);
}

// Copies a temporary upload to its permanent place under a new random name.
async function commit(kind, tmpKey, ext) {
  const key = `${crypto.randomUUID()}.${ext}`;
  await fsp.copyFile(safePath('tmp', tmpKey), safePath(kind, key), fs.constants.COPYFILE_EXCL);
  return key;
}

const commitBook = (tmpKey, ext) => commit('books', tmpKey, ext);
const commitCover = (tmpKey, ext) => commit('covers', tmpKey, ext);

// Deletes a file. A missing file is fine.
async function remove(kind, key) {
  try {
    await fsp.unlink(safePath(kind, key));
  } catch (err) {
    if (err.code !== 'ENOENT') console.error('Could not delete file:', err.message);
  }
}

function coverUrl(key) {
  return `${env.publicApiUrl}/media/covers/${key}`;
}

module.exports = { dirs, init, commitBook, commitCover, remove, coverUrl };